/* The ppl runtime: the functions compiled ppl programs call.
 *
 * Every symbol is prefixed with `ppl_`. Strings are passed as (pointer, byte length) pairs of
 * UTF-8 without a terminating NUL. */
#ifndef PPL_RT_H
#define PPL_RT_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* The program's entry point, generated by the compiler. */
void ppl_entry(void);

/* A string: immutable UTF-8 with its byte length and its length in code points. `cache_*`
 * remember the last indexed position so sequential `s[i]` is O(1) (mutable even in literals,
 * which are therefore emitted as writable globals). */
typedef struct PplStr {
    int64_t byte_len;
    int64_t char_len;
    int64_t cache_char;
    int64_t cache_byte;
    char data[];
} PplStr;

/* Memory. v0 is backed by malloc and never frees; the GC (P4.x) keeps this API. Never
 * returns NULL: running out of memory aborts the program. */
void *ppl_alloc(int64_t size);
void *ppl_alloc_zeroed(int64_t size); /* class instances */
/* Whether `obj` (an object, possibly null) is an instance of the class whose metadata is
 * `info`. An object's first word points at its class's metadata, whose first word points at
 * the base class's (null at the root). */
int32_t ppl_instance_of(const void *obj, const void *info);

/* A growable array (`T[]`): `len` elements of the element size the compiler passes, stored
 * contiguously at `data` (zeroed beyond `len` up to `cap`). */
typedef struct PplArray {
    int64_t len;
    int64_t cap;
    char *data;
} PplArray;

PplArray *ppl_array_new(int64_t elem_size, int64_t len); /* `len` zeroed elements */
void *ppl_array_push(PplArray *a, int64_t elem_size);    /* appends a slot, returns it */
int32_t ppl_array_pop(PplArray *a);                      /* 1 if an element was removed */
PplArray *ppl_array_slice(const PplArray *a, int64_t elem_size, int64_t start, int64_t end);

/* Strings. */
PplStr *ppl_str_new(const char *bytes, int64_t byte_len); /* counts code points */
PplStr *ppl_str_concat(const PplStr *a, const PplStr *b);
int32_t ppl_str_eq(const PplStr *a, const PplStr *b); /* null-safe (for `string?`) */
int32_t ppl_str_cmp(const PplStr *a, const PplStr *b); /* <0, 0, >0 in code-point order */
/* String forms of primitives (templates, `toString()`), as `println` shows them. */
PplStr *ppl_str_from_i64(int64_t v);
PplStr *ppl_str_from_u64(uint64_t v);
PplStr *ppl_str_from_f64(double v);
PplStr *ppl_str_from_f32(float v);
PplStr *ppl_str_from_bool(int32_t v);
PplStr *ppl_str_from_char(uint32_t c);

/* A compiled format spec (`${x:08.2f}`), emitted by the compiler as a constant. Field values
 * mirror `ppl_sema::format::FormatSpec`. */
typedef struct PplFmt {
    uint32_t fill;
    int32_t align;     /* 0 none, 1 left, 2 right, 3 center */
    int32_t sign;      /* 0 minus, 1 plus, 2 space */
    int32_t alternate; /* `#` */
    int32_t zero;      /* `0` */
    int32_t width;     /* -1: none */
    int32_t precision; /* -1: none */
    int32_t kind;      /* 0 default, 1 d, 2 x, 3 X, 4 o, 5 b, 6 e, 7 E, 8 f, 9 %, 10 ? */
} PplFmt;

PplStr *ppl_fmt_i64(int64_t v, const PplFmt *f);
PplStr *ppl_fmt_u64(uint64_t v, const PplFmt *f);
PplStr *ppl_fmt_f64(double v, int32_t is_f32, const PplFmt *f);
PplStr *ppl_fmt_str(const PplStr *s, const PplFmt *f);
PplStr *ppl_fmt_char(uint32_t c, const PplFmt *f);
PplStr *ppl_fmt_bool(int32_t v, const PplFmt *f);

/* The char at code-point index `i`; panics (index out of bounds) at the given location.
 * Sequential access is O(1) thanks to the cached position. */
uint32_t ppl_str_char_at(PplStr *s, int64_t i, const char *file, int64_t file_len, int32_t line,
                         int32_t col);

/* Printing to stdout (buffered; flushed at exit and before a panic). */
void ppl_print_i64(int64_t v);
void ppl_print_u64(uint64_t v);
void ppl_print_f64(double v);
void ppl_print_f32(float v);
void ppl_print_bool(int32_t v); /* 0 or 1 */
void ppl_print_char(uint32_t c);
void ppl_print_str(const char *ptr, int64_t len);
void ppl_print_string(const PplStr *s);
void ppl_print_newline(void);

/* Writes the JavaScript-style text of a number (Number.prototype.toString) into `buf`, which
 * needs room for 32 bytes. Returns the length. */
int ppl_format_f64(double v, char *buf);
int ppl_format_f32(float v, char *buf);

/* Prints "panic: <msg>\n  at <file>:<line>:<col>\n" to stderr and exits with code 101. */
_Noreturn void ppl_panic(const char *msg, int64_t msg_len, const char *file, int64_t file_len,
                         int32_t line, int32_t col);

_Noreturn void ppl_panic_str(const PplStr *msg, const char *file, int64_t file_len, int32_t line,
                             int32_t col);

/* Integer power for `**`: `exp` is non-negative; sets *overflow if the result doesn't fit in
 * a `bits`-wide signed (`_s`) or unsigned (`_u`) integer. */
int64_t ppl_ipow_s(int64_t base, int64_t exp, int32_t bits, int32_t *overflow);
uint64_t ppl_ipow_u(uint64_t base, uint64_t exp, int32_t bits, int32_t *overflow);

/* Hashing for derived `hashCode` (the interpreter computes the same values). */
uint64_t ppl_hash_u64(uint64_t x);           /* splitmix64 */
uint64_t ppl_hash_str(const PplStr *s);      /* FNV-1a over the UTF-8 bytes */
uint64_t ppl_hash_combine(uint64_t a, uint64_t b);

#define PPL_PANIC_EXIT_CODE 101

#endif
